// Telegram entrega las notas de voz como `.oga` y Groq rechaza esa
// extension, aunque el contenido sea exactamente el mismo OGG/Opus que si
// acepta: valida por el nombre del archivo, no por el contenido.
//
// Aqui SOLO se renombra. No se reconvierte nada y el audio no se toca.
for (const item of $input.all()) {
  const b = item.binary && item.binary.data;
  if (b) {
    b.fileName = 'nota.ogg';
    b.fileExtension = 'ogg';
    b.mimeType = 'audio/ogg';
  }
}
return $input.all();

// La transcripcion tambien se guarda, para que la nota de voz sea
// buscable dentro de la nube y no solo dentro de Telegram.
const texto = ($json.text || '').trim();
if (!texto) { return []; }

// Monterrey es UTC-6 todo el ano desde 2022, sin horario de verano. El sello
// va en hora local para que el nombre coincida con cuando lo mandaste.
const l = new Date(Date.now() - 6 * 3600 * 1000);
const sello = l.toISOString().slice(0, 16).replace('T', ' ').replace(':', '');
// El id del mensaje evita que dos notas del mismo minuto se pisen.
const id = $('Buzon').first().json.message.message_id;
const final = sello + ' - voz ' + id + '.txt';

return [{
  json: { rutaNombre: final },
  binary: {
    data: {
      data: Buffer.from(texto, 'utf8').toString('base64'),
      mimeType: 'text/plain',
      fileName: final
    }
  }
}];

// Cada tipo de mensaje guarda el archivo en un sitio distinto del payload.
// Aqui se normaliza a un solo par: que bajar y como llamarlo.
const m = $json.message;
let fileId = null;
let nombre = 'archivo';

if (m.photo) {
  // Telegram manda la MISMA foto en varias resoluciones; la ultima es la mayor.
  // Quedarse con otra guardaria una miniatura sin que nada avisara.
  fileId = m.photo[m.photo.length - 1].file_id;
  nombre = 'foto.jpg';
} else if (m.video) {
  fileId = m.video.file_id;
  nombre = m.video.file_name || 'video.mp4';
} else if (m.video_note) {
  fileId = m.video_note.file_id;
  nombre = 'videonota.mp4';
} else if (m.document) {
  fileId = m.document.file_id;
  nombre = m.document.file_name || 'documento';
}

return [{ json: { fileId: fileId, nombre: nombre } }];

// El nombre lleva fecha y hora delante para que la carpeta se ordene sola
// por cuando llegaron las cosas, que es como uno las busca.
//
// ⚠️ Y lleva el id del mensaje al final, que NO es decoracion. Un album de
// Telegram son varios mensajes en el mismo minuto y todas sus fotos se
// llamarian igual: se sobrescribirian entre ellas y solo quedaria la ultima,
// sin que nada avisara. Paso con cinco fotos reales.
const l = new Date(Date.now() - 6 * 3600 * 1000);
const sello = l.toISOString().slice(0, 16).replace('T', ' ').replace(':', '');
const nombre = $('Que archivo es').first().json.nombre;
const id = $('Buzon').first().json.message.message_id;

const punto = nombre.lastIndexOf('.');
const base = punto > 0 ? nombre.slice(0, punto) : nombre;
const ext = punto > 0 ? nombre.slice(punto) : '';
const final = sello + ' - ' + base + ' ' + id + ext;

for (const item of $input.all()) {
  const b = item.binary && item.binary.data;
  if (b) { b.fileName = final; }
  item.json = { rutaNombre: final };
}
return $input.all();

// Un mensaje de texto se guarda como .txt, con las primeras palabras en el
// nombre para poder encontrarlo en la carpeta sin abrirlo.
const texto = ($json.message.text || '').trim();
if (!texto) { return []; }

const l = new Date(Date.now() - 6 * 3600 * 1000);
const sello = l.toISOString().slice(0, 16).replace('T', ' ').replace(':', '');

// Se filtra por lista blanca en vez de prohibir caracteres: los nombres de
// archivo tienen reglas distintas en Windows, Android y Linux, y esta carpeta
// se sincroniza a los tres.
const PERMITIDOS = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789 .,-_áéíóúüñÁÉÍÓÚÜÑ';
let titulo = '';
for (const c of texto) {
  titulo += PERMITIDOS.indexOf(c) >= 0 ? c : ' ';
}
titulo = titulo.replace('  ', ' ').trim().slice(0, 40).trim() || 'nota';

// El id del mensaje evita que dos notas del mismo minuto que empiecen igual
// se sobrescriban entre ellas.
const id = $json.message.message_id;
const final = sello + ' - ' + titulo + ' ' + id + '.txt';
return [{
  json: { rutaNombre: final },
  binary: {
    data: {
      data: Buffer.from(texto, 'utf8').toString('base64'),
      mimeType: 'text/plain',
      fileName: final
    }
  }
}];

// Se pasa por base64 y se decodifica aqui en vez de usar la operacion de
// texto del nodo: `binaryToPropery` es la unica via de este nodo que ya
// esta comprobada en este flujo, y un comando que falla en silencio no se
// distingue de un bot que te ignora.
const b64 = $json.textoB64 || '';
const texto = Buffer.from(b64, 'base64').toString('utf8').trim();
return [{ json: { respuesta: texto || 'Todavia no hay resumen. Manda un ticket primero.' } }];

// El borrado NO se hace aqui: se deja una orden que recoge el proceso del
// servidor, igual que con las altas. Escribir el .xlsx desde el bot es lo
// que se pierde cuando tienes el libro abierto en Excel.
const id = $('Buzon').first().json.message.message_id;
const orden = { pedido: 'borrar-ultimo', desde: 'telegram', id: id };
return [{
  json: {
    ruta: 'borrar-' + id + '.json',
    respuesta: 'Quitando el ultimo gasto del libro.\nEn menos de un minuto ya no esta. Comprueba con /gastos.'
  },
  binary: {
    orden: {
      data: Buffer.from(JSON.stringify(orden), 'utf8').toString('base64'),
      mimeType: 'application/json',
      fileName: 'borrar-' + id + '.json'
    }
  }
}];

// Se arma el cuerpo aqui y no en el nodo HTTP porque la imagen va en base64
// dentro del JSON: meterla en una expresion del nodo seria ilegible.
//
// ⚠️ El base64 llega ya resuelto por el nodo anterior, y esto NO es un rodeo.
// n8n guarda los binarios en DISCO (`filesystem-v2`), asi que
// `$binary.data.data` no trae la imagen sino el literal "filesystem-v2", 13
// caracteres: mandarlo tal cual hizo que Groq contestara "failed to decode
// base64 data". Y `this.helpers.getBinaryDataBuffer` tampoco vale: no existe
// dentro del sandbox de este nodo. El nodo `Sacar el base64` es la via buena.
const b64 = $json.imagenB64;
if (!b64 || b64.length < 100) { throw new Error('La imagen no llego como base64.'); }
const tipo = $('Bajar el ticket').first().binary.data.mimeType || 'image/jpeg';

// ⚠️ Las categorias son LISTA CERRADA y salen de la hoja `Categorias` del
// libro. Con texto libre, a las dos semanas todo dice "varios" y el
// Dashboard deja de sumar nada util: sus SUMIFS comparan contra estos
// nombres exactos.
const CATEGORIAS = ['Comida', 'Transporte', 'Vivienda', 'Servicios', 'Suscripciones',
                    'Compras', 'Entretenimiento', 'Salud', 'Viajes', 'Otros'];

const instrucciones = [
  'Lee este ticket de compra mexicano y responde SOLO con un objeto JSON.',
  'Sin explicaciones, sin texto antes ni despues, sin bloques de codigo.',
  '',
  'Formato exacto:',
  '{"fecha":"AAAA-MM-DD","hora":"HH:MM","comercio":"...","total":0.00,"metodo_pago":"Efectivo|Tarjeta|Transferencia","categoria":"...","descripcion":"..."}',
  '',
  'Reglas:',
  '- total es el importe FINAL pagado, no el subtotal ni antes de impuestos.',
  '- categoria debe ser exactamente una de: ' + CATEGORIAS.join(', '),
  '- descripcion: tres o cuatro palabras sobre que se compro.',
  '- Si un dato no aparece en el ticket, pon null. Menos categoria, que siempre eliges la mas cercana.',
  '- Las fechas mexicanas suelen venir DD/MM/AAAA: no las confundas con MM/DD.'
].join('\n');

return [{
  json: {
    cuerpo: {
      model: 'qwen/qwen3.6-27b',
      temperature: 0,
      // ⚠️ Este modelo RAZONA en voz alta: escribe un bloque <think> largo antes
      // de contestar. Con 500 tokens se quedaba sin espacio pensando y nunca
      // llegaba al JSON --devolvia finish_reason "length"--, aunque habia
      // leido el ticket bien. `reasoning_effort: none` le quita el monologo y
      // el limite alto queda de red por si lo ignora.
      reasoning_effort: 'none',
      max_completion_tokens: 2000,
      messages: [{
        role: 'user',
        content: [
          { type: 'text', text: instrucciones },
          { type: 'image_url', image_url: { url: 'data:' + tipo + ';base64,' + b64 } }
        ]
      }]
    }
  },
  binary: $('Bajar el ticket').first().binary
}];

// Interpreta lo que devolvio el modelo y prepara las dos cosas que hay que
// guardar: el apunte del gasto y la foto del ticket como comprobante.
const eleccion = ($json.choices && $json.choices[0]) || {};
const crudo = (eleccion.message && eleccion.message.content) || '';

// Si se quedo sin espacio, no hay JSON que rescatar y conviene decirlo con
// esas palabras en vez de fallar al parsear algo que nunca llego.
if (eleccion.finish_reason === 'length') {
  throw new Error('El modelo se quedo sin espacio antes de responder. Sube max_completion_tokens.');
}

// ⚠️ Dos cosas que ensucian la respuesta y hay que quitar en este orden:
// el bloque <think> de los modelos que razonan en voz alta, y las vallas
// ```json que ponen aunque se les pida que no. Buscar la primera llave SIN
// quitar el <think> antes encontraria una llave del monologo.
const texto = crudo.replace(/<think>[\s\S]*?<\/think>/g, '').replace(/```[a-z]*/gi, '').trim();
const ini = texto.indexOf('{');
const fin = texto.lastIndexOf('}');
if (ini === -1 || fin <= ini) {
  throw new Error('No hay JSON en la respuesta: ' + texto.slice(0, 200));
}

let d;
try {
  d = JSON.parse(texto.slice(ini, fin + 1));
} catch (e) {
  throw new Error('JSON invalido: ' + texto.slice(ini, ini + 200));
}

const monto = Number(d.total);
if (!Number.isFinite(monto) || monto <= 0) {
  throw new Error('No pude leer el importe del ticket. Devolvio: ' + JSON.stringify(d));
}

const l = new Date(Date.now() - 6 * 3600 * 1000);
const hoy = l.toISOString().slice(0, 10);
const sello = l.toISOString().slice(0, 16).replace('T', ' ').replace(':', '');
const id = $('Buzon').first().json.message.message_id;

// Si el ticket no traia fecha, se usa la de hoy: un gasto sin fecha no entra
// en ningun mes y desaparece del Dashboard sin que nada avise.
const fecha = /^\d{4}-\d{2}-\d{2}$/.test(d.fecha || '') ? d.fecha : hoy;
const comprobante = sello + ' - ticket ' + id + '.jpg';

const gasto = {
  fecha: fecha,
  hora: /^\d{2}:\d{2}$/.test(d.hora || '') ? d.hora : sello.slice(11, 13) + ':' + sello.slice(13, 15),
  categoria: d.categoria || 'Otros',
  descripcion: d.descripcion || '',
  monto: Math.round(monto * 100) / 100,
  metodoPago: d.metodo_pago || '',
  comercio: d.comercio || '',
  comprobante: comprobante
};

const aviso = [
  'Gasto apuntado:',
  '',
  'Comercio:  ' + (gasto.comercio || '(no lo vi)'),
  'Importe:   $' + gasto.monto.toFixed(2),
  'Fecha:     ' + gasto.fecha + (fecha === hoy && d.fecha !== hoy ? '  (no venia en el ticket)' : ''),
  'Pago:      ' + (gasto.metodoPago || '(no lo vi)'),
  'Categoria: ' + gasto.categoria,
  '',
  'Aparece en el libro en menos de un minuto.',
  'Si algo esta mal, corrigelo en Excel.'
].join('\n');

return [{
  json: {
    rutaPendiente: 'gasto-' + id + '.json',
    rutaComprobante: comprobante,
    aviso: aviso
  },
  binary: {
    data: $('Bajar el ticket').first().binary.data,
    pendiente: {
      data: Buffer.from(JSON.stringify(gasto, null, 2), 'utf8').toString('base64'),
      mimeType: 'application/json',
      fileName: 'gasto-' + id + '.json'
    }
  }
}];
